            elif color == 2:
                path = [(r, cc) for cc in range(c, c - 5, -1)]
            elif color == 3:
                path = [(rr, c) for rr in range(r, r + 4)]
            else:  # color 6
                path = [(rr, c) for rr in range(r, r - 7, -1)]
            paths.append((color, path, (r + dr, c + dc)))

    for color, path, end in paths:
        for rr, cc in path[1:]:
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 5
        rr, cc = end
        if 0 <= rr < h and 0 <= cc < w:
